from code.run import extract_facts, build_rows
from code.loader import load_dataset
from pathlib import Path
import csv, json

root = Path('/Users/snehsinha/Documents/hackerrank/hackerrank-orchestrate-october26')
ds = load_dataset(root)
facts = extract_facts(root, refresh=True)
rows = build_rows(root, facts, mode='eval')

# B14: Completeness - for each INCOMPLETE case, every FINDING has a REMEDIATION 
# and every REMEDIATION has a VERIFICATION on the same system/resource

incomplete_cases = [r for r in rows if r['deletion_status'] == 'INCOMPLETE']

# Check that every INCOMPLETE case has the FINDING->REMEDIATION->VERIFICATION structure
issues = []
for case in incomplete_cases:
    steps = case['steps']
    finding_steps = [s for s in steps if s['phase'] == 'FINDING']
    remediation_steps = [s for s in steps if s['phase'] == 'REMEDIATION']
    verification_steps = [s for s in steps if s['phase'] == 'VERIFICATION']

    # Check: every FINDING has a corresponding REMEDIATION
    if len(finding_steps) > 0 and len(remediation_steps) == 0:
        issues.append(f'{case[\"case_id\"]}: has FINDINGs but no REMEDIATION')

    # Check: every REMEDIATION has a corresponding VERIFICATION
    if len(remediation_steps) > 0 and len(verification_steps) == 0:
        issues.append(f'{case[\"case_id\"]}: has REMEDIATIONs but no VERIFICATION')

    # Check: FINDING and REMEDIATION/VEREFICATION are on the same system/resource
    for fs in finding_steps:
        for rs in remediation_steps:
            if fs['system_id'] == rs['system_id'] and fs['resource_id'] == rs['resource_id']:
                break
        else:
            issues.append(f'{case[\"case_id\"]}: FINDING {fs[\"system_id\"]}.{fs[\"resource_id\"]} has no matching REMEDIATION')

    for rs in remediation_steps:
        matched = False
        for vs in verification_steps:
            if rs['system_id'] == vs['system_id'] and rs['resource_id'] == vs['resource_id']:
                matched = True
                break
        if not matched:
            issues.append(f'{case[\"case_id\"]}: REMEDIATION {rs[\"system_id\"]}.{rs[\"resource_id\"]} has no matching VERIFICATION')

    if len(issues) > 0 and case['case_id'] in [i.split(':')[0] for i in issues[:10]]:
        pass  # Just track unique cases

if issues:
    print(f'Completeness issues found: {len(issues)}')
    for i in issues[:10]:
        print(f'  {i}')
else:
    print('All INCOMPLETE cases have proper FINDING->REMEDIATION->VERIFICATION structure - PASS')

# Also check COMPLETE cases have only VERIFICATION steps
complete_cases = [r for r in rows if r['deletion_status'] == 'COMPLETE']
comp_issues = []
for case in complete_cases[:20]:
    steps = case['steps']
    non_verification = [s for s in steps if s['phase'] != 'VERIFICATION']
    if non_verification:
        comp_issues.append(f'{case[\"case_id\"]}: has {len(non_verification)} non-VERIFICATION steps')

    # Also check that COMPLETE cases don't have evidence_id='' on verification steps
    # Actually, COMPLETE steps should have evidence_id citing the evidence
    for s in steps:
        if s['evidence_id'] == '' and s['operation'] in ('VERIFY_RECORD_ABSENT', 'VERIFY_RECORD_PRESENT'):
            # This is OK for INCOMPLETE but might be an issue for COMPLETE
            pass

if comp_issues:
    print(f'COMPLETE case issues: {len(comp_issues)}')
    for i in comp_issues[:5]:
        print(f'  {i}')
else:
    print('COMPLETE cases have only VERIFICATION steps - PASS')
