a={r['case_id']:r for r in csv.DictReader(open('output.csv'))}
for f in ('status_mut.csv','result_mut.csv'):
    b={r['case_id']:r for r in csv.DictReader(open(TMP+'/'+f))}
    cats=collections.Counter(); detail=[]
    for cid in a:
        sa=json.loads(a[cid]['steps_json']); sb=json.loads(b[cid]['steps_json'])
        if sa==sb: continue
        aa=[s for s in sa if s['system_id']=='account_service' and s['phase']=='VERIFICATION']
        ba=[s for s in sb if s['system_id']=='account_service' and s['phase']=='VERIFICATION']
        if len(aa)==len(ba)==1 and aa[0]['operation']==ba[0]['operation'] and aa[0]['state']==ba[0]['state']:
            cats['account_id_swap']+=1; detail.append((cid,'swap',aa[0]['resource_id'],ba[0]['resource_id']))
        elif len(aa)==1 and not ba:
            cats['account_step_dropped']+=1; detail.append((cid,'drop',aa[0]['resource_id'],None))
        elif not aa and len(ba)==1:
            cats['account_step_added']+=1; detail.append((cid,'add',None,ba[0]['resource_id']))
        else:
            cats['other']+=1; detail.append((cid,'other',[(s['resource_id'],s['step_no']) for s in aa],[(s['resource_id'],s['step_no']) for s in ba]))
